S.append(S2(c,B+' · 1','List: dãy có thứ tự, thay đổi được',card('Đặc điểm',P('Viết trong <b>[ ]</b>, các phần tử cách nhau dấu phẩy, <b>có thể khác kiểu</b>.','Có chỉ số, cắt lát <b>giống xâu</b>, nhưng <b>thay đổi được</b> (mutable).','<code>len(a)</code> số phần tử; phần tử cuối là <code>a[-1]</code>.')),CODE('a = [3, 1, 4, 1, 5, 9, 2, 6]\nprint(a[2:5], a[::3], a[-3:], sum(a[-3:]))\na[0] = 10\nprint(a, len(a))',22)+R('a = [3, 1, 4, 1, 5, 9, 2, 6]\nprint(a[2:5], a[::3], a[-3:], sum(a[-3:]))\na[0] = 10\nprint(a, len(a))','',22,'Kết quả')+KEY('<code>a[::3]</code> lấy chỉ số 0, 3, 6: 3, 1, 2. <code>sum(a[-3:])</code> = 9 + 2 + 6 = 17.')))
S.append(TB(c,B+' · 1','Các thao tác thêm, xoá, tìm',['Thao tác','Ý nghĩa','Ví dụ'],[['<code>a.append(x)</code>','thêm x vào cuối',V('a=[1,2]\na.append(3)\nprint(a)')],['<code>a.insert(i, x)</code>','chèn x vào vị trí i',V('a=[1,3]\na.insert(1,2)\nprint(a)')],['<code>a.pop()</code> / <code>a.pop(i)</code>','xoá và <b>trả về</b> phần tử cuối / thứ i',V('a=[1,2,3]\nprint(a.pop(), a.pop(0), a)')],['<code>a.remove(x)</code>','xoá x <b>đầu tiên</b> tìm thấy',V('a=[1,2,1]\na.remove(1)\nprint(a)')],['<code>a.index(x)</code>','vị trí x đầu tiên (lỗi nếu không có)',V('print([5,6,7].index(7))')],['<code>x in a</code>','có trong danh sách không',V('print(3 in [1,2,3])')],['<code>a.extend(b)</code> hoặc <code>a + b</code>','nối danh sách',V('a=[1]\na.extend([2,3])\nprint(a, a+[4])')]],note=KEY('<b>append, insert, pop, remove, extend, sort, reverse</b> đều <b>sửa trực tiếp</b> danh sách và <b>trả về None</b>.')))
S.append(S2(c,B+' · 1','Bẫy: các hàm sửa trực tiếp trả về None',card('Nhầm lẫn kinh điển',P('<code>b = a.append(5)</code> làm b = <b>None</b>.','<code>b = a.sort()</code> làm b = <b>None</b>, và a đã bị sắp xếp.','Muốn danh sách mới đã sắp xếp: <b>sorted(a)</b>.')),CODE('a = [4, 1, 3]\nb = a.sort()\nc = sorted([4, 1, 3], reverse=True)\nprint(b, a, c)\nx = [1, 2]\ny = x.append(3)\nprint(x, y)',22)+R('a = [4, 1, 3]\nb = a.sort()\nc = sorted([4, 1, 3], reverse=True)\nprint(b, a, c)\nx = [1, 2]\ny = x.append(3)\nprint(x, y)','',22,'Kết quả')+WARN('Lỗi phổ biến: <code>a = a.sort()</code> làm mất danh sách (a thành None).')))
S.append(S2(c,B+' · 2','Gán b = a không tạo bản sao',card('Hai tên, một danh sách',P('<b>b = a</b>: b và a là <b>hai tên của cùng một danh sách</b>; đổi qua tên nào cũng thấy cả hai.','<b>c = a[:]</b> (hoặc <code>a.copy()</code>, <code>list(a)</code>) tạo <b>bản sao nông</b>: danh sách mới, các phần tử vẫn cùng đối tượng.')),CODE('a = [5, 3, 8, 1]\nb = a\nb.append(7)\nc = a[:]\nc.sort()\nprint(a, b)\nprint(c)\nprint(a is b, a is c)',22)+R('a = [5, 3, 8, 1]\nb = a\nb.append(7)\nc = a[:]\nc.sort()\nprint(a, b)\nprint(c)\nprint(a is b, a is c)','',22,'Kết quả')+KEY('<code>a is b</code>: cùng đối tượng. Bản sao c sắp xếp <b>không ảnh hưởng</b> a.')))
S.append(S2(c,B+' · 2','Sao chép nông và sao chép sâu',card('Danh sách lồng nhau',P('Bản sao <b>nông</b> chỉ sao chép lớp ngoài; <b>danh sách bên trong vẫn dùng chung</b>.','Sao chép <b>sâu</b>: sao chép cả các danh sách con (<code>copy.deepcopy</code> hoặc tự sao chép từng con).')),CODE('a = [1, [2, 3], 4]\nb = a\nc = a[:]\nd = [x[:] if isinstance(x, list) else x for x in a]\nb[0] = 9\nc[1].append(7)\nd[1].append(8)\nprint(a, c, d)',21)+R('a = [1, [2, 3], 4]\nb = a\nc = a[:]\nd = [x[:] if isinstance(x, list) else x for x in a]\nb[0] = 9\nc[1].append(7)\nd[1].append(8)\nprint(a, c, d)','',20,'Kết quả')+KEY('b[0] = 9 đổi <b>a</b> (cùng đối tượng). <code>c[1].append(7)</code> đổi danh sách con dùng chung với a. d độc lập hoàn toàn.')))
S.append(S2(c,B+' · 2','Truyền danh sách vào hàm',card('Hàm có thể làm đổi danh sách gốc',P('Tham số nhận <b>tham chiếu</b> đến danh sách: sửa bên trong hàm là <b>sửa danh sách gốc</b>.','Gán lại tham số (<code>a = ...</code>) chỉ đổi tên cục bộ, không đổi bên ngoài.')),CODE('def f(a):\n    a.append(0)\n\ndef g(a):\n    a = a + [0]\n    return a\n\nx = [1]\nf(x)\nprint(x)\ng(x)\nprint(x)\ny = g(x)\nprint(x, y)',21)+R('def f(a):\n    a.append(0)\n\ndef g(a):\n    a = a + [0]\n    return a\n\nx = [1]\nf(x)\nprint(x)\ng(x)\nprint(x)\ny = g(x)\nprint(x, y)','',22,'Kết quả')))
S.append(S2(c,B+' · 2','Sắp xếp: sort, sorted, key',card('Hai cách',T(tr('','a.sort()','sorted(a)',h=True)+tr('Sửa a?','<b>Có</b>','Không')+tr('Trả về','None','danh sách mới')+tr('Dùng được cho','chỉ list','mọi dãy'))+P('Tham số: <code>reverse=True</code> giảm dần; <code>key=hàm</code> sắp xếp theo giá trị hàm. Sắp xếp <b>ổn định</b> (giữ thứ tự gốc khi bằng nhau).')),CODE('t = ["lan", "an", "binh", "ha"]\nprint(sorted(t))\nprint(sorted(t, key=len))\nprint(sorted(t, key=lambda w: (-len(w), w)))\nds = [(3, "c"), (1, "z"), (3, "a")]\nds.sort(key=lambda p: (-p[0], p[1]))\nprint(ds)',20)+R('t = ["lan", "an", "binh", "ha"]\nprint(sorted(t))\nprint(sorted(t, key=len))\nprint(sorted(t, key=lambda w: (-len(w), w)))\nds = [(3, "c"), (1, "z"), (3, "a")]\nds.sort(key=lambda p: (-p[0], p[1]))\nprint(ds)','',20,'Kết quả')+KEY('Khoá là <b>bộ</b> (tuple) sắp xếp theo từng thành phần; dấu − đảo chiều với số.')))
