S.append(S2(c,B+' · 3','List comprehension: tạo danh sách trong một dòng',card('Cú pháp',P('<code>[biểu_thức for x in dãy if điều_kiện]</code>','Đọc: “với mỗi x trong dãy (nếu thoả điều kiện), lấy biểu thức”.','Tương đương vòng for + append, nhưng gọn hơn.')),CODE('a = [x * x for x in range(1, 8) if x % 2]\nb = [c.upper() for c in "tin"]\nc = [(i, j) for i in range(2) for j in range(2)]\nprint(a)\nprint(b)\nprint(c)',22)+R('a = [x * x for x in range(1, 8) if x % 2]\nb = [c.upper() for c in "tin"]\nc = [(i, j) for i in range(2) for j in range(2)]\nprint(a)\nprint(b)\nprint(c)','',22,'Kết quả')+KEY('x lẻ từ 1 đến 7: 1, 3, 5, 7 → bình phương: 1, 9, 25, 49.')))
S.append(S2(c,B+' · 3','zip và enumerate',card('Duyệt song song và đánh số',P('<b>zip(a, b)</b> ghép từng cặp, <b>dừng ở dãy ngắn nhất</b>.','<b>enumerate(a)</b> cho cặp (chỉ số, giá trị).','<code>zip(a, a[1:])</code> cho các <b>cặp kề nhau</b>.')),CODE('a = [4, 8, 15, 16, 23, 42]\nb = [x * x for x in a if x % 2 == 0]\nc = {x % 5 for x in a}\nd = list(zip(a, a[1:]))\ne = [i for i, x in enumerate(a) if x > 15]\nprint(b, c, d[:2], len(d), e)',20)+R('a = [4, 8, 15, 16, 23, 42]\nb = [x * x for x in a if x % 2 == 0]\nc = {x % 5 for x in a}\nd = list(zip(a, a[1:]))\ne = [i for i, x in enumerate(a) if x > 15]\nprint(b, c, d[:2], len(d), e)','',20,'Kết quả')+KEY('6 phần tử ghép với 5 phần tử kế → chỉ <b>5 cặp</b>. Tập c = {0,1,2,3,4} (5 phần tử).')))
S.append(S2(c,B+' · 3','Hàm có sẵn cho danh sách',card('Hay dùng',ul(['<code>sum, min, max, len</code>.','<code>any(ds)</code>: có ít nhất một phần tử đúng.','<code>all(ds)</code>: tất cả đều đúng.','<code>a.count(x)</code>, <code>a.reverse()</code>, <code>reversed(a)</code>.','<code>list(map(int, input().split()))</code>: đọc dãy số.'],7)),CODE('a = [3, 8, 1, 9, 4, 7]\nprint(sum(a), min(a), max(a), len(a))\nprint(any(x > 8 for x in a), all(x > 0 for x in a))\nb = a[1::2] + a[::-2]\nprint(b, sum(b[:3]), max(b[2:]))',21)+R('a = [3, 8, 1, 9, 4, 7]\nprint(sum(a), min(a), max(a), len(a))\nprint(any(x > 8 for x in a), all(x > 0 for x in a))\nb = a[1::2] + a[::-2]\nprint(b, sum(b[:3]), max(b[2:]))','',22,'Kết quả')+KEY('<code>a[1::2]</code> = [8, 9, 7]; <code>a[::-2]</code> = [7, 9, 8] (từ cuối, lùi hai).')))
S.append(S2(c,B+' · 3','Bẫy: xoá phần tử khi đang duyệt',card('Không nên',P('Xoá phần tử của danh sách <b>trong lúc for duyệt chính nó</b> làm các phần tử sau dồn chỗ nên bị <b>bỏ sót</b>.','Cách đúng: duyệt <b>bản sao</b>, hoặc <b>tạo danh sách mới</b> bằng comprehension.')),CODE('a = [2, 4, 6, 7]\nfor x in a:\n    if x % 2 == 0:\n        a.remove(x)\nprint(a)\nb = [2, 4, 6, 7]\nb = [x for x in b if x % 2]\nprint(b)',22)+R('a = [2, 4, 6, 7]\nfor x in a:\n    if x % 2 == 0:\n        a.remove(x)\nprint(a)\nb = [2, 4, 6, 7]\nb = [x for x in b if x % 2]\nprint(b)','',24,'Kết quả')+KEY('Cách sai chỉ xoá 2 và 6 (bỏ sót 4) vì sau khi xoá 2, số 4 nhảy lên vị trí 0 và bị bỏ qua.')))
# tuple set dict
S.append(S2(c,B+' · 4','Tuple (bộ): dãy bất biến',card('Đặc điểm',P('Viết trong <b>( )</b>: <code>t = (3, 5)</code>. <b>Không sửa được</b> sau khi tạo.','Tuple một phần tử phải có <b>dấu phẩy</b>: <code>(5,)</code>.','Hay dùng để <b>trả nhiều giá trị</b> từ hàm, làm <b>khoá</b> của dict, và <b>phần tử của set</b>.')),CODE('t = (3, 5)\nx, y = t\nprint(x + y, t[0], len(t))\nprint(type((5)), type((5,)))\ndef f(a, b):\n    return a + b, a * b\nprint(f(3, 4))\nt[0] = 9',22)+R('t = (3, 5)\nx, y = t\nprint(x + y, t[0], len(t))\nprint(type((5)), type((5,)))\ndef f(a, b):\n    return a + b, a * b\nprint(f(3, 4))','',22,'Kết quả')+RES(OUT(ERR('t = (3, 5)\nt[0] = 9'),20),'Dòng cuối gây lỗi')))
S.append(S2(c,B+' · 4','Set (tập hợp): không trùng, không thứ tự',card('Đặc điểm và phép toán',P('Viết trong <b>{ }</b>; <b>tự loại phần tử trùng</b>, <b>không có chỉ số</b>. Tập rỗng là <code>set()</code> (không phải {}).','Kiểm tra <code>x in s</code> <b>rất nhanh</b> (trung bình O(1)).','Phép toán: <b>|</b> hợp, <b>&amp;</b> giao, <b>−</b> hiệu, <b>^</b> hiệu đối xứng.')),CODE('a = {1, 2, 3, 4}\nb = {3, 4, 5}\nprint(a | b, a & b)\nprint(a - b, a ^ b)\nprint(len({1, 1, 2, 2, 3}), 3 in a)\nprint(len(set([4, 8, 15, 16, 23, 42, 4])))\nprint(type({}), type(set()))',21)+R('a = {1, 2, 3, 4}\nb = {3, 4, 5}\nprint(a | b, a & b)\nprint(a - b, a ^ b)\nprint(len({1, 1, 2, 2, 3}), 3 in a)\nprint(len(set([4, 8, 15, 16, 23, 42, 4])))\nprint(type({}), type(set()))','',20,'Kết quả')))
S.append(S2(c,B+' · 4','Dict (từ điển): ánh xạ khoá → giá trị',card('Đặc điểm',P('Viết <b>{khoá: giá_trị}</b>; khoá <b>không trùng</b> và phải <b>bất biến</b> (số, xâu, tuple).','Tra cứu theo khoá <b>rất nhanh</b>: <code>d[k]</code>; khoá không có → <b>KeyError</b>; dùng <code>d.get(k, mặc_định)</code> để an toàn.','Duyệt: <code>d.items()</code>, <code>d.keys()</code>, <code>d.values()</code>.')),CODE('d = {"an": 8, "binh": 6}\nd["chi"] = 9\nd["an"] += 1\nprint(d, len(d))\nprint(d.get("hoa", 0), "an" in d)\nfor ten, diem in d.items():\n    print(ten, diem)\nprint(max(d, key=d.get))',20)+R('d = {"an": 8, "binh": 6}\nd["chi"] = 9\nd["an"] += 1\nprint(d, len(d))\nprint(d.get("hoa", 0), "an" in d)\nfor ten, diem in d.items():\n    print(ten, diem)\nprint(max(d, key=d.get))','',20,'Kết quả')+KEY('<b>in</b> kiểm tra <b>khoá</b>, không kiểm tra giá trị.')))
S.append(S2(c,B+' · 4','Dict comprehension và đếm tần suất',card('Ví dụ',P('<code>{x: x % 3 for x in range(6)}</code> tạo dict x → x mod 3.','Đếm tần suất phần tử dãy: dict + <code>get</code>, hoặc <code>Counter</code> (module collections).')),CODE('b = {x: x % 3 for x in range(6)}\nprint(b, b[5])\nfrom collections import Counter\ncnt = Counter([3, 1, 3, 2, 3, 1])\nprint(cnt, cnt.most_common(1))\ntan = {}\nfor x in [3, 1, 3, 2, 3, 1]:\n    tan[x] = tan.get(x, 0) + 1\nprint(tan)',20)+R('b = {x: x % 3 for x in range(6)}\nprint(b, b[5])\nfrom collections import Counter\ncnt = Counter([3, 1, 3, 2, 3, 1])\nprint(cnt, cnt.most_common(1))\ntan = {}\nfor x in [3, 1, 3, 2, 3, 1]:\n    tan[x] = tan.get(x, 0) + 1\nprint(tan)','',20,'Kết quả')))
S.append(TB(c,B+' · 4','So sánh bốn kiểu dữ liệu',['','list','tuple','set','dict'],[['Kí hiệu','[1, 2]','(1, 2)','{1, 2}','{k: v}'],['Thứ tự','có','có','<b>không</b>','giữ thứ tự thêm vào'],['Sửa được','có','<b>không</b>','có','có'],['Trùng','cho phép','cho phép','<b>không</b>','khoá không trùng'],['Tra cứu','theo chỉ số','theo chỉ số','x in s (nhanh)','theo khoá (nhanh)'],['Dùng khi','dãy dữ liệu','bộ cố định, khoá dict','loại trùng, kiểm tra thuộc','tra cứu, đếm tần suất']],note=KEY('Kiểm tra <code>x in list</code> mất O(n); <code>x in set</code> hoặc <code>x in dict</code> chỉ O(1). Đây là lí do bài “có phần tử trùng” dùng set thay vì list.')))
S.append(S2(c,B+' · 4','Phát hiện phần tử trùng: list chậm, set nhanh',card('So sánh hai cách',P('<b>Dùng list</b> <code>seen</code>: mỗi lần <code>x in seen</code> duyệt cả list → tổng <b>O(n²)</b>.','<b>Dùng set</b>: kiểm tra và thêm đều O(1) trung bình → tổng <b>O(n)</b>.','Cách ngắn nhất: <code>len(set(a)) != len(a)</code>.')),CODE('def co_trung(a):\n    seen = set()\n    for x in a:\n        if x in seen:\n            return True\n        seen.add(x)\n    return False\nprint(co_trung([3, 1, 4, 1]), co_trung([1, 2, 3]))\nprint(len(set([3, 1, 4, 1])) != 4)',21)+R('def co_trung(a):\n    seen = set()\n    for x in a:\n        if x in seen:\n            return True\n        seen.add(x)\n    return False\nprint(co_trung([3, 1, 4, 1]), co_trung([1, 2, 3]))\nprint(len(set([3, 1, 4, 1])) != 4)','',22,'Kết quả')))
S.append(SELF(c,B+' · 5','Tự kiểm tra: sao chép','Cho a = [5, 3, 8, 1]; b = a; b.append(7); c = a[:]; c.sort(). In a, c.','a = [5, 3, 8, 1]\nb = a\nb.append(7)\nc = a[:]\nc.sort()\nprint(a, c)',P('b là tên khác của a → <code>b.append(7)</code> làm <b>a = [5, 3, 8, 1, 7]</b>.','c là bản sao (chụp sau khi a đã có 7) → [5, 3, 8, 1, 7]; sort → <b>[1, 3, 5, 7, 8]</b> và a không đổi.')+R('a = [5, 3, 8, 1]\nb = a\nb.append(7)\nc = a[:]\nc.sort()\nprint(a, c)','',22,'Kết quả thật'),21))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): phát biểu đúng/sai','Cho: a = [4, 8, 15, 16, 23, 42]; d = list(zip(a, a[1:])). Có đúng “d có 6 cặp” không? Tập {x % 5 for x in a} có mấy phần tử?','a = [4, 8, 15, 16, 23, 42]\nd = list(zip(a, a[1:]))\nprint(len(d), len({x % 5 for x in a}))',P('<b>zip dừng ở dãy ngắn nhất</b>: a có 6, a[1:] có 5 → d có <b>5</b> cặp. Phát biểu “6 cặp” là <b>sai</b>.','Dư khi chia 5: 4, 3, 0, 1, 3, 2 → tập {0, 1, 2, 3, 4} có <b>5</b> phần tử (3 trùng được loại).')+R('a = [4, 8, 15, 16, 23, 42]\nd = list(zip(a, a[1:]))\nprint(len(d), len({x % 5 for x in a}))','',24,'Kết quả thật'),21))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): ngăn xếp bằng list','Chương trình sau in ra gì? Giải thích bằng bảng theo dõi ngăn xếp st.','st = []\nkq = []\nfor ch in "abcdef":\n    st.append(ch)\n    if len(st) == 3:\n        kq.append(st.pop())\n        kq.append(st.pop())\nprint(kq, st)',P('Thêm a, b → st = [a, b]; thêm c → st = [a, b, c], đủ 3: pop c, pop b → kq = [c, b], st = [a].','Thêm d → [a, d]; thêm e → [a, d, e], đủ 3: pop e, pop d → kq = [c, b, e, d], st = [a].','Thêm f → [a, f] (2 phần tử, chưa đủ 3). Kết quả: <b>kq = [c, b, e, d], st = [a, f]</b>.')+R('st = []\nkq = []\nfor ch in "abcdef":\n    st.append(ch)\n    if len(st) == 3:\n        kq.append(st.pop())\n        kq.append(st.pop())\nprint(kq, st)','',22,'Kết quả thật'),20))
S+=END(c,B,['List: <b>mutable</b>, có chỉ số, cắt lát như xâu; tuple <b>bất biến</b>; set <b>không trùng</b>; dict <b>khoá → giá trị</b>.','<b>b = a</b> là hai tên một danh sách; <b>a[:]</b> là bản sao nông; lồng nhau cần sao chép <b>sâu</b>.','<b>sort()</b> sửa tại chỗ, trả None; <b>sorted()</b> trả danh sách mới; <b>key</b> chọn tiêu chí.','<b>Comprehension</b>, <b>zip</b> (dừng ở dãy ngắn), <b>enumerate</b>.','<b>in</b> trên set/dict nhanh O(1), trên list chậm O(n).','Hàm <b>sửa trực tiếp</b> danh sách tham số làm đổi danh sách gốc.'],[('Bản sao nông','a[:], a.copy()'),('Sắp xếp mới','sorted(a)'),('Tập rỗng','set()'),('Cặp kề','zip(a, a[1:])')],'Gán a = a.sort(); quên sao chép sâu; xoá phần tử khi đang duyệt.',['<code>(5)</code> không phải tuple; phải <code>(5,)</code>.','<code>{}</code> là dict rỗng, <b>không phải</b> set.','<code>[[0]*3]*3</code> tạo các hàng <b>trùng nhau</b>.','Khoá dict phải bất biến.'],['<b>collections</b>: Counter, deque, defaultdict.','<b>heapq</b> (hàng đợi ưu tiên).','<b>bisect</b> tìm kiếm nhị phân trên list.'],
 [('<code>[1,2,3][::-1]</code>?',),('<code>len({1,2,2,3})</code>?',),('<code>b = a.copy()</code> khác <code>b = a</code> ở đâu?',),('<code>sorted([3,1,2], reverse=True)</code>?',),('<code>d.get("x", 0)</code> khi d không có “x”?',)],
 [('<b>[3, 2, 1]</b>.',),('<b>3</b>.',),('<b>copy</b> tạo danh sách mới; <b>b = a</b> dùng chung.',),('<b>[3, 2, 1]</b>.',),('<b>0</b> (không lỗi).',)],
 [('Mức 1. Nhập dãy số, in các số chẵn theo thứ tự ban đầu. Thử 4 7 2 9 6.',),('Mức 1. Đếm số phần tử <b>khác nhau</b> của dãy. Thử 3 1 3 2 3 1.',),('Mức 2. In số lần xuất hiện của mỗi giá trị, theo thứ tự giá trị tăng dần. Thử 3 1 3 2 3 1.',),('Mức 2. Sắp xếp danh sách học sinh (tên, điểm) giảm dần theo điểm; bằng nhau xếp theo tên.',),('Mức 3 (HSG). Cho dãy a, đếm số cặp (i &lt; j) có a[i] + a[j] = k bằng dict trong O(n). Thử a = 3 1 4 1 5 9 2 6, k = 7.',),('Mức 3 (HSG). Tìm <b>độ dài dãy con liên tiếp dài nhất</b> gồm các phần tử đôi một khác nhau. Thử 2 3 4 3 5 6 2 7.',)],
 [(V('a=[4,7,2,9,6]\nprint([x for x in a if x%2==0])')+'.',),(V('print(len(set([3,1,3,2,3,1])))')+' giá trị khác nhau.',),(V('a=[3,1,3,2,3,1]\nfor v in sorted(set(a)):\n    print(v,a.count(v),end="; ")')+'.',),('<code>ds.sort(key=lambda p: (-p[1], p[0]))</code>.',),('Duyệt từng x, cộng <code>dem[k - x]</code> rồi tăng <code>dem[x]</code> → '+V('a=[3,1,4,1,5,9,2,6]\nk=7\nd={}\nt=0\nfor x in a:\n    t+=d.get(k-x,0)\n    d[x]=d.get(x,0)+1\nprint(t)')+' cặp.',),('Cửa sổ trượt với set/dict ghi vị trí gần nhất → '+V('a=[2,3,4,3,5,6,2,7]\nvt={}\nl=0\nbest=0\nfor r,x in enumerate(a):\n    if x in vt and vt[x]>=l:\n        l=vt[x]+1\n    vt[x]=r\n    best=max(best,r-l+1)\nprint(best)')+'.',)],hper=2)
